function debounce(fn, wait) {
    let t;
    return (...args) => {
        clearTimeout(t);
        t = setTimeout(() => fn.apply(this, args), wait);
    };
}
class PredictiveSearch extends HTMLElement {
    constructor() {
        super();
        this.cachedResultsMarkupHtml = {};
        this.cachedResultsMarkup = {};
        this.input = this.querySelector('input[type="search"]');
        this.clearInput = this.querySelector('.js-clear-search-input');
        this.predictiveSearchResults = this.querySelector('[data-predictive-search-results]');
        this.setupEventListeners();
    }

    setupEventListeners() {
        let _this = this;
        this.input.addEventListener('input', debounce((event) => {
            this.onChange(event);
        }, 300).bind(this));
        this.clearInput.addEventListener('click',function (){
            let inputWrapper = this.closest('.input-group');
            let input = inputWrapper.querySelector('input[type="search"]');
            input.value = "";
            _this.predictiveSearchResults.innerHTML = "";
			this.style.display = 'none'
        })
    }

    getQuery() {
        return this.input.value.trim();
    }

    onChange() {
        this.input.closest('.input-group').classList.add('loading');
        const searchTerm = this.getQuery();
        if (!searchTerm.length) {
            this.close(true);
			this.clearInput.style.display = 'none'
            return;
        }
        this.getSearchResults(searchTerm);
		this.clearInput.removeAttribute('style')
    }

    getSearchResults(searchTerm) {
        const queryKey = searchTerm.replace(" ", "-").toLowerCase();
        if (this.cachedResultsMarkup[queryKey] && this.cachedResultsMarkupHtml[queryKey]) {
            this.renderSearchResults(this.cachedResultsMarkup[queryKey], this.cachedResultsMarkupHtml[queryKey]);
            return;
        }
        fetch(`${ window.routes.predictive_search_url}?q=${encodeURIComponent(searchTerm)}&${encodeURIComponent('resources[type]')}=product,query&${encodeURIComponent('resources[limit]')}=10&section_id=predictive-search`)
            .then((response) => {
                if (!response.ok) {
                    var error = new Error(response.status);
                    throw error;
                    this.close();
                }
                return response.text();
            })
            .then((text) => {
                const doc = new DOMParser().parseFromString(text, 'text/html');
                const resultsMarkup = doc.querySelector('#shopify-section-predictive-search').querySelector('#predictive-search-results');
                const resultsMarkupHtml = doc.querySelector('#shopify-section-predictive-search').querySelector('#predictive-search-results').innerHTML;
                if(resultsMarkupHtml.length > 0){
                    this.cachedResultsMarkupHtml[queryKey] = resultsMarkupHtml;
                    this.cachedResultsMarkup[queryKey] = resultsMarkupHtml;
                    this.renderSearchResults(resultsMarkup,resultsMarkupHtml);
                }else{
                    this.close();
                }
            })
            .catch((error) => {
                throw error;
            });
    }

    renderSearchResults(resultsMarkup,resultsMarkupHtml) {
        let resultsMarkupType = typeof resultsMarkup;
        let resultsMarkupObj = resultsMarkup;
        if(resultsMarkupHtml.trim().length > 0) {
            if(resultsMarkupType == 'string'){
                resultsMarkupObj = new DOMParser().parseFromString(resultsMarkup, 'text/html');
            }

            this.predictiveSearchResults.innerHTML = resultsMarkupObj.querySelector('[data-predictive-search-results]').innerHTML;
			reloadProductCardHover();
            this.open();
        }
    }
    open() {
		this.input.closest('.input-group').classList.remove('loading')
		if (document.querySelector('#header-search')) {
			document.querySelector('#header-search').style.height = document.querySelector('#header-search').scrollHeight + 'px';
		}
    }

    close(clearSearchTerm = false) {
		this.input.closest('.input-group').classList.remove('loading')
		this.predictiveSearchResults.innerHTML = "";
		if (document.querySelector('#header-search')) {
			document.querySelector('#header-search').style.height = document.querySelector('#header-search .header-search-form-wrapper').getBoundingClientRect().height + 'px';
		}
    }
}
customElements.define('predictive-search', PredictiveSearch);
